<?php
if(!is_admin() && !can('can_view_reports')){echo '<div class="card">Reports permission denied.</div>';return;}
$today=db()->query("SELECT COUNT(*) orders,COALESCE(SUM(total),0) sales FROM orders WHERE DATE(created_at)=CURDATE() AND status<>'cancelled'")->fetch();
$paid=db()->query("SELECT payment_method,COUNT(*) count,COALESCE(SUM(total),0) total FROM orders WHERE payment_status='paid' GROUP BY payment_method")->fetchAll();
$items=db()->query("SELECT item_name,SUM(qty) qty,SUM(qty*unit_price) total FROM order_items oi JOIN orders o ON o.id=oi.order_id WHERE DATE(o.created_at)=CURDATE() AND o.status<>'cancelled' GROUP BY item_name ORDER BY qty DESC LIMIT 20")->fetchAll();
?><h1 class="h1">Reports</h1><div class="cards"><div class="card">Orders Today<div class="stat"><?=$today['orders']?></div></div><div class="card">Sales Today<div class="stat"><?=e(currency_symbol())?><?=number_format($today['sales'],2)?></div></div></div><div class="row"><div class="card"><h2>Payment Summary</h2><table class="table"><tr><th>Method</th><th>Orders</th><th>Total</th></tr><?php foreach($paid as $p): ?><tr><td><?=e($p['payment_method'])?></td><td><?=$p['count']?></td><td><?=e(currency_symbol())?><?=number_format($p['total'],2)?></td></tr><?php endforeach;?></table></div><div class="card"><h2>Top Items Today</h2><table class="table"><tr><th>Item</th><th>Qty</th><th>Total</th></tr><?php foreach($items as $i): ?><tr><td><?=e($i['item_name'])?></td><td><?=$i['qty']?></td><td><?=e(currency_symbol())?><?=number_format($i['total'],2)?></td></tr><?php endforeach;?></table></div></div>